function makeWorld(){buildings=[];trees=[];rocks=[];loot=[];const spots=[[-16,-12,7,5],[-5,-18,8,5],[8,-13,7,6],[20,-17,8,5],[-22,2,6,8],[-11,5,8,6],[5,4,9,7],[20,5,8,6],[-15,20,8,6],[0,20,10,7],[17,22,8,6]];spots.forEach(([x,z,w,d],i)=>buildings.push({x,z,w,d,h:rand(3.2,7.5),color:['#f58c5b','#f4c655','#4eafb0','#ee6e80','#b88ad7'][i%5],roof:['#397b85','#d76f56','#547e63'][i%3],kind:i%3}));for(let i=0;i<100;i++){let x=rand(-54,54),z=rand(-54,54);if(Math.hypot(x,z)<6)continue;if(buildings.some(b=>Math.abs(x-b.x)<b.w*.7&&Math.abs(z-b.z)<b.d*.7))continue;(Math.random()<.78?trees:rocks).push({x,z,s:rand(.65,1.45),kind:Math.floor(rand(0,3))});}for(let i=0;i<17;i++){let x=rand(-39,39),z=rand(-39,39);if(Math.hypot(x,z)<8)continue;loot.push({x,z,type:['rifle','shield','med','ammo'][i%4],phase:rand(0,6)});}}
