function project(x,z,y=0){const f={x:Math.sin(player.heading),z:Math.cos(player.heading)},r={x:Math.cos(player.heading),z:-Math.sin(player.heading)};const camx=player.x-f.x*5,camz=player.z-f.z*5;const dx=x-camx,dz=z-camz,depth=dx*f.x+dz*f.z,side=dx*r.x+dz*r.z;const focal=Math.min(W,H)*.86,scale=focal/(depth+2.6);return {x:W*.5+side*scale,y:H*.47+(1.15-y)*scale,depth,scale};}
function polygon(points,fill,stroke='#263747',lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}}
function renderWorld(){let sky=ctx.createLinearGradient(0,0,0,H*.68);sky.addColorStop(0,'#6bc6d1');sky.addColorStop(.63,'#b0e5cf');sky.addColorStop(1,'#e1e6ae');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const horizon=H*.37;ctx.fillStyle='#9bd3a4';ctx.fillRect(0,horizon,W,H-horizon);
// distant hills
for(let i=0;i<8;i++){let x=i*W/6-W*.12;ctx.fillStyle=['#7ebd9c','#78b596','#68a78c'][i%3];ctx.beginPath();ctx.moveTo(x,horizon+22);ctx.quadraticCurveTo(x+W*.13,horizon-60-(i%3)*16,x+W*.26,horizon+22);ctx.lineTo(x+W*.26,horizon+44);ctx.lineTo(x,horizon+44);ctx.fill();}
// broad stylized grass tiles projected from world grid
for(let z=70;z>=2;z-=4){for(let x=-70;x<=70;x+=4){const p1=project(x,z),p2=project(x+4,z),p3=project(x+4,z+4),p4=project(x,z+4);if(p1.depth<0||p1.depth>95)continue;let shade=((Math.floor(x/4)+Math.floor(z/4))%2===0)?'#82c579':'#79bc70';polygon([p1,p2,p3,p4],shade,null);}}
// paths and roads
for(let z=-70;z<80;z+=2){const a=project(-2.2,z),b=project(2.2,z),c=project(2.2,z+2),d=project(-2.2,z+2);polygon([a,b,c,d],(Math.floor(z/2)%2?'#cfbd8b':'#d6c99c'),null)}
// zone ring
if(zone.r>0){ctx.save();ctx.setLineDash([12,8]);ctx.lineWidth=2;ctx.strokeStyle='rgba(119,242,255,.62)';const pts=[];for(let i=0;i<=80;i++){let a=i/80*Math.PI*2,p=project(zone.x+Math.cos(a)*zone.r,zone.z+Math.sin(a)*zone.r,.04);pts.push(p)}ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore();}
let renderables=[];buildings.forEach(b=>renderables.push({type:'building',o:b,d:project(b.x,b.z).depth}));trees.forEach(o=>renderables.push({type:'tree',o,d:project(o.x,o.z).depth}));rocks.forEach(o=>renderables.push({type:'rock',o,d:project(o.x,o.z).depth}));loot.forEach(o=>renderables.push({type:'loot',o,d:project(o.x,o.z).depth}));enemies.filter(e=>e.alive).forEach(o=>renderables.push({type:'enemy',o,d:project(o.x,o.z).depth}));renderables.sort((a,b)=>b.d-a.d).forEach(it=>{if(it.d>0&&it.d<90){if(it.type==='building')drawBuilding(it.o);if(it.type==='tree')drawTree(it.o);if(it.type==='rock')drawRock(it.o);if(it.type==='loot')drawLoot(it.o);if(it.type==='enemy')drawEnemy(it.o)}});
// small cloud streaks and vignetting
ctx.fillStyle='rgba(255,255,255,.37)';for(let i=0;i<4;i++){let x=((i*317+elapsed*2)%(W+200))-100,y=H*.14+(i%2)*36;ctx.beginPath();ctx.ellipse(x,y,48,7,0,0,7);ctx.fill();}
if(scene==='playing')drawPlayerAvatar();}
function drawBuilding(b){const p=project(b.x,b.z),s=p.scale;if(s<.7)return;let w=b.w*s,h=b.h*s,d=b.d*s;if(w>W*1.1||h>H*1.4)return;let bx=p.x-w/2,by=p.y-h;const dep=d*.35;polygon([{x:bx, y:p.y},{x:bx+w,y:p.y},{x:bx+w,y:by},{x:bx,y:by}],b.color,'#263643',Math.max(1,s*.04));polygon([{x:bx+w,y:p.y},{x:bx+w+dep,y:p.y-dep*.28},{x:bx+w+dep,y:by-dep*.28},{x:bx+w,y:by}],shadeColor(b.color,-30),'#263643',Math.max(1,s*.04));polygon([{x:bx-4*s,y:by},{x:bx+w*.5,y:by-h*.13},{x:bx+w+4*s,y:by},{x:bx+w,y:by+2*s},{x:bx,y:by+2*s}],b.roof,'#263643',Math.max(1,s*.04));let winW=Math.max(2,w*.11),winH=Math.max(3,h*.17);for(let i=0;i<3;i++){for(let j=0;j<2;j++){ctx.fillStyle=i===1?'#ffe9a7':'#9de2d7';ctx.fillRect(bx+w*(.19+j*.48),by+h*(.25+i*.23),winW,winH);ctx.fillStyle='rgba(20,50,59,.4)';ctx.fillRect(bx+w*(.19+j*.48),by+h*(.25+i*.23)+winH*.75,winW,Math.max(1,winH*.25));}}ctx.fillStyle='#263747';ctx.fillRect(bx+w*.43,by+h*.63,w*.16,h*.37);if(b.kind===0){ctx.fillStyle='#f9de65';ctx.fillRect(bx+w*.46,by-h*.14,w*.1,h*.14);}}
function shadeColor(hex,amount){let n=parseInt(hex.slice(1),16),r=clamp((n>>16)+amount,0,255),g=clamp((n>>8&255)+amount,0,255),b=clamp((n&255)+amount,0,255);return '#'+(1<<24|r<<16|g<<8|b).toString(16).slice(1)}
function drawTree(o){const p=project(o.x,o.z),s=p.scale*o.s;if(s<1)return;ctx.fillStyle='#705239';ctx.fillRect(p.x-s*.12,p.y-s*.9,s*.24,s*.9);let c=['#299776','#42a879','#268875'][o.kind];ctx.fillStyle='#1f654f';ctx.beginPath();ctx.arc(p.x-s*.05,p.y-s*1.16,s*.53,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(p.x,p.y-s*1.38,s*.43,0,7);ctx.fill();ctx.fillStyle='#79cf85';ctx.beginPath();ctx.arc(p.x-s*.16,p.y-s*1.49,s*.21,0,7);ctx.fill();ctx.fillStyle='rgba(255,255,255,.2)';ctx.beginPath();ctx.arc(p.x-s*.17,p.y-s*1.52,s*.09,0,7);ctx.fill();}
function drawRock(o){const p=project(o.x,o.z),s=p.scale*o.s;if(s<1)return;polygon([{x:p.x-s*.65,y:p.y},{x:p.x-s*.51,y:p.y-s*.58},{x:p.x-s*.1,y:p.y-s*.85},{x:p.x+s*.55,y:p.y-s*.53},{x:p.x+s*.72,y:p.y},{x:p.x,y:p.y+s*.04}],o.kind===0?'#aaa88a':'#948d78','#526354',Math.max(1,s*.035));}
function drawLoot(o){const p=project(o.x,o.z),s=p.scale;if(s<1)return;let col=o.type==='shield'?'#65e4ff':o.type==='med'?'#ff7376':o.type==='rifle'?'#d8ff3e':'#f6c55f',bob=Math.sin(elapsed*3+o.phase)*s*.08;ctx.save();ctx.shadowColor=col;ctx.shadowBlur=Math.min(18,s*.24);ctx.fillStyle=col;ctx.beginPath();ctx.arc(p.x,p.y-s*.55+bob,Math.max(3,s*.12),0,7);ctx.fill();ctx.restore();polygon([{x:p.x-s*.28,y:p.y-s*.12+bob},{x:p.x+s*.28,y:p.y-s*.12+bob},{x:p.x+s*.4,y:p.y+s*.06},{x:p.x-s*.4,y:p.y+s*.06}],col,'#253a43',Math.max(1,s*.025));if(s>10){ctx.fillStyle='#fff';ctx.font=`${Math.max(7,s*.17)}px sans-serif`;ctx.textAlign='center';ctx.fillText(o.type==='shield'?'✦':o.type==='med'?'✚':o.type==='rifle'?'⌁':'▦',p.x,p.y-s*.14+bob)}}

