function drawMinimap(){const w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#759e71';mctx.fillRect(0,0,w,h);mctx.save();mctx.translate(w/2-player.x*1.65,h/2-player.z*1.65);mctx.rotate(-player.heading);mctx.scale(1.65,1.65);mctx.fillStyle='#c8bd8c';mctx.fillRect(-1.5,-45,3,90);buildings.forEach(b=>{mctx.fillStyle=b.color;mctx.fillRect(b.x-b.w/2,b.z-b.d/2,b.w,b.d)});trees.forEach(t=>{mctx.fillStyle='#328b62';mctx.beginPath();mctx.arc(t.x,t.z,1.5,0,7);mctx.fill()});loot.forEach(l=>{mctx.fillStyle=l.type==='shield'?'#58d8f4':'#ecdb58';mctx.fillRect(l.x-.7,l.z-.7,1.4,1.4)});enemies.filter(e=>e.alive).forEach(e=>{mctx.fillStyle='#f77869';mctx.beginPath();mctx.arc(e.x,e.z,1.1,0,7);mctx.fill()});mctx.strokeStyle='rgba(106,234,255,.9)';mctx.lineWidth=.8;mctx.beginPath();mctx.arc(zone.x,zone.z,zone.r,0,7);mctx.stroke();mctx.fillStyle='#e6ff3d';mctx.beginPath();mctx.moveTo(0,-4);mctx.lineTo(2.5,3);mctx.lineTo(0,2);mctx.lineTo(-2.5,3);mctx.fill();mctx.restore();}
function updateHUD(){ $('hp-number').textContent=Math.ceil(player.health);$('shield-number').textContent=Math.ceil(player.shield);$('hp-fill').style.width=player.health+'%';$('shield-fill').style.width=(player.shield/100*100)+'%';$('ammo-now').textContent=player.weapon===0?player.ammo:player.smg;$('ammo-reserve').textContent=player.weapon===0?player.reserve:player.reserve*2;$('remaining-count').textContent=remaining;$('shield-items').textContent='×'+player.shieldItems;$('med-items').textContent='×'+player.medItems;let mm=Math.floor(zone.timer/60),ss=Math.floor(zone.timer%60);$('zone-timer').textContent=String(mm).padStart(2,'0')+':'+String(ss).padStart(2,'0');$('weapon-type').textContent=player.weapon===0?'RIFLE DE ASSALTO':'SUBMETRALHADORA';$('weapon-icon').textContent=player.weapon===0?'⌁':'⌖';}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function feed(text){let el=document.createElement('div');el.className='feed-entry';el.innerHTML=text;$('kill-feed').prepend(el);setTimeout(()=>el.remove(),4000)}
function particleBurst(x,z,color,n=12){for(let i=0;i<n;i++){let an=rand(0,Math.PI*2),speed=rand(1,6);particles.push({x,z,vx:Math.cos(an)*speed,vz:Math.sin(an)*speed,y:rand(.2,1.8),life:rand(.22,.6),max:.6,color})}}
function nearestLoot(){let target=null,best=2.7;loot.forEach(l=>{let d=dist(player,l);if(d<best){best=d;target=l}});return target}
function collect(){let l=nearestLoot();if(!l){toast('NENHUM ITEM POR PERTO');return}if(l.type==='shield'){player.shield=Math.min(100,player.shield+30);toast('ESCUDO +30')}else if(l.type==='med'){player.health=Math.min(100,player.health+35);toast('CURA +35')}else if(l.type==='ammo'){player.reserve+=36;toast('MUNIÇÃO +36')}else{player.reserve+=30;toast('RIFLE • MUNIÇÃO +30')}audio('loot');particleBurst(l.x,l.z,l.type==='med'?'#ff7376':'#d8ff3e',18);loot.splice(loot.indexOf(l),1);updateHUD()}
function useItem(type){if(type==='shield'&&player.shieldItems>0&&player.shield<100){player.shieldItems--;player.shield=Math.min(100,player.shield+45);toast('ESCUDO EQUIPADO +45');audio('loot')}else if(type==='med'&&player.medItems>0&&player.health<100){player.medItems--;player.health=Math.min(100,player.health+50);toast('KIT MÉDICO • +50 HP');audio('loot')}else if(type==='weapon'){player.weapon=1-player.weapon;toast(player.weapon?'SUBMETRALHADORA EQUIPADA':'RIFLE EQUIPADO')}else toast('ITEM INDISPONÍVEL');updateHUD()}
function reload(){if(reloadTimer>0)return;let cur=player.weapon===0?player.ammo:player.smg,cap=player.weapon===0?24:40;if(cur>=cap||player.reserve<=0){toast('SEM MUNIÇÃO PARA RECARREGAR');return}reloadTimer=player.weapon===0?1.25:1.55;$('reload-indicator').classList.add('active');audio('loot')}
function finishReload(){let key=player.weapon===0?'ammo':'smg',cap=player.weapon===0?24:40,need=cap-player[key],take=Math.min(need,player.reserve);player[key]+=take;player.reserve-=take;reloadTimer=0;$('reload-indicator').classList.remove('active');updateHUD();}
function shoot(){if(scene!=='playing'||reloadTimer>0)return;let key=player.weapon===0?'ammo':'smg';if(player[key]<=0){reload();return}let rate=player.weapon===0?.19:.095;if(fireTimer>0)return;fireTimer=rate;player[key]--;shotFlash=.09;audio('shoot');let best=null,bestScore=Infinity;const forward={x:Math.sin(player.heading),z:Math.cos(player.heading)},right={x:Math.cos(player.heading),z:-Math.sin(player.heading)};for(const e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dz=e.z-player.z,along=dx*forward.x+dz*forward.z,side=Math.abs(dx*right.x+dz*right.z);let threshold=player.weapon===0?1.35:1.8;if(along>1&&along<38&&side<along*(W>700?.085:.13)+threshold){let score=side/along;if(score<bestScore){bestScore=score;best=e}}}shots.push({x:player.x+forward.x*.9,z:player.z+forward.z*.9,tx:best?.x??player.x+forward.x*25,tz:best?.z??player.z+forward.z*25,life:.16});particleBurst(player.x+forward.x*1.2,player.z+forward.z*1.2,'#ffe79a',3);if(best&&Math.random()<clamp(1-bestScore*5,.25,.9)){let dmg=player.weapon===0?29:13;if(best.shield>0){let take=Math.min(best.shield,dmg);best.shield-=take;dmg-=take}best.hp-=dmg;hitTimer=.16;audio('hit');particleBurst(best.x,best.z,'#fff07a',9);if(best.hp<=0){best.alive=false;remaining--;player.kills++;feed(`<b>${agents[agentIndex].name}</b>  ✕  ${best.name}`);toast('ELIMINAÇÃO • '+best.name);audio('loot');if(Math.random()<.7)loot.push({x:best.x,z:best.z,type:Math.random()<.5?'shield':'med',phase:rand(0,5)});if(remaining===1)winGame();}}updateHUD();}
function winGame(){scene='won';$('center-message').querySelector('span').textContent='VITÓRIA ROYALE';$('center-message').querySelector('b').textContent='VOCÊ DOMINOU A ILHA';$('center-message').classList.add('show');}
function loseGame(){scene='dead';$('center-message').querySelector('span').textContent='ELIMINADO';$('center-message').querySelector('b').textContent='A ILHA AINDA TE ESPERA';$('center-message').classList.add('show');audio('hit')}
function damage(amount){if(player.shield>0){let take=Math.min(player.shield,amount);player.shield-=take;amount-=take}player.health=Math.max(0,player.health-amount);updateHUD();if(player.health<=0)loseGame();}

